//! The conformance vector suite of `11-conformance.md` §7, read by a second
//! implementation. Until this ran, "portable" was a claim: the vectors were
//! generated by the implementation they test, so they caught regression but
//! not misreading.
//!
//! Everything here consumes only JSON and this crate's public encode and
//! decode paths.

#[path = "support_v/mod.rs"]
mod support;

use cryptand::value::{NumType, Value};
use cryptand::{catalog, cke, container, cve, filter, hash, index, security};
use support::{build, hex, load, unhex};

// ---------------------------------------------------------------------------
// cke/values -- spec/03-key-encoding.md
// ---------------------------------------------------------------------------

#[test]
fn cke_cases_encode_to_their_recorded_bytes() {
    let v = load("cke/values");
    for c in v["cases"].as_array().unwrap() {
        let value = build(&c["value"]);
        let got = cke::encode(&value).expect("every case is key-encodable");
        assert_eq!(hex(&got), c["cke"].as_str().unwrap(), "{:?}", value);
    }
}

#[test]
fn cke_cases_decode_back() {
    let v = load("cke/values");
    for c in v["cases"].as_array().unwrap() {
        let bytes = unhex(c["cke"].as_str().unwrap());
        let got = cke::decode_all(&bytes).unwrap_or_else(|e| panic!("{}: {e}", c["cke"]));
        let want = build(&c["value"]);
        // The three lossy decodings of §7 have their own test; here the
        // vector's own case list is round-trippable except for those, which
        // this re-encode check tolerates by comparing bytes, not values.
        let reencoded = cke::encode(&got).unwrap();
        assert_eq!(hex(&reencoded), c["cke"].as_str().unwrap(), "{:?} -> {:?}", want, got);
    }
}

#[test]
fn cke_rejects_are_rejected_and_none_of_them_panics() {
    let v = load("cke/values");
    for r in v["rejects"].as_array().unwrap() {
        let bytes = unhex(r["cke"].as_str().unwrap());
        let got = cke::decode_all(&bytes);
        assert!(got.is_err(), "{} must be rejected: {}", r["cke"], r["why"]);
    }
}

