#[test]
fn the_recorded_sort_order_is_the_byte_order() {
    let v = load("numbers/torture");
    let sorted: Vec<Vec<u8>> =
        v["sorted_by_cke"].as_array().unwrap().iter().map(|s| unhex(s.as_str().unwrap())).collect();
    for i in 1..sorted.len() {
        assert!(sorted[i - 1] <= sorted[i], "entry {i} breaks the recorded order");
    }
    // And the recorded order is the order this implementation produces.
    let mut mine: Vec<Vec<u8>> = v["entries"]
        .as_array()
        .unwrap()
        .iter()
        .map(|e| cke::encode(&build(&e["value"])).unwrap())
        .collect();
    mine.sort();
    assert_eq!(mine, sorted, "the sorted vector is not what this encoder produces");
}

/// §1's invariant, in both clauses. The vector states it in prose; this checks
/// it over all 170 x 170 pairs against a logical comparison built without the
/// encoder.
#[test]
fn cke_order_refines_logical_order() {
    let v = load("numbers/torture");
    let vals: Vec<Value> = v["entries"].as_array().unwrap().iter().map(|e| build(&e["value"])).collect();
    let keys: Vec<Vec<u8>> = vals.iter().map(|x| cke::encode(x).unwrap()).collect();
    let mut compared = 0usize;
    for i in 0..vals.len() {
        for j in 0..vals.len() {
            let Some(logical) = logical_cmp(&vals[i], &vals[j]) else { continue };
            compared += 1;
            let bytes = keys[i].cmp(&keys[j]);
            if logical != std::cmp::Ordering::Equal {
                assert_eq!(
                    bytes, logical,
                    "clause 1: {:?} vs {:?} -- memcmp {:?}, logical {:?}",
                    vals[i], vals[j], bytes, logical
                );
            } else {
                // Clause 2: equal values are either the same key, or differ
                // only in the trailing type code, and are therefore adjacent
                // inside [N(v), successor(N(v))).
                let (a, b) = (&keys[i], &keys[j]);
                assert_eq!(a[..a.len() - 1], b[..b.len() - 1], "clause 2: {:?} vs {:?}", vals[i], vals[j]);
                let n = cke::n_of(&vals[i]).unwrap();
                let upper = cke::successor(&n).unwrap();
                assert!(a >= &n && a < &upper, "clause 2: {:?} outside [N(v), successor)", vals[i]);
                assert!(b >= &n && b < &upper, "clause 2: {:?} outside [N(v), successor)", vals[j]);
            }
        }
    }
    assert!(compared > 10_000, "too few comparable pairs to mean anything: {compared}");
}

/// An exact logical comparison (`02-value-encoding.md` §8 rule 2) that does not
/// go through CKE. `None` where an exact comparison would need arbitrary
/// precision -- an integer above 2^53 against a float -- rather than a lossy one.
fn logical_cmp(a: &Value, b: &Value) -> Option<std::cmp::Ordering> {
    use std::cmp::Ordering;
    let as_f = |v: &Value| -> Option<f64> {
        match v {
            Value::Float { v, .. } => Some(*v),
            Value::Int { neg, mag, .. } if *mag <= (1u128 << 53) => {
                Some(if *neg { -(*mag as f64) } else { *mag as f64 })
            }
            _ => None,
        }
    };
    match (a, b) {
        (Value::Int { neg: n1, mag: m1, .. }, Value::Int { neg: n2, mag: m2, .. }) => {
            let sign = |n: &bool, m: &u128| if *m == 0 { 0i32 } else if *n { -1 } else { 1 };
            let (s1, s2) = (sign(n1, m1), sign(n2, m2));
            Some(if s1 != s2 {
                s1.cmp(&s2)
            } else if s1 < 0 {
                m2.cmp(m1)
            } else {
                m1.cmp(m2)
            })
        }
        _ => {
            let (x, y) = (as_f(a)?, as_f(b)?);
            // §8 rule 3: NaN equals NaN and sorts above every other number.
            Some(match (x.is_nan(), y.is_nan()) {
                (true, true) => Ordering::Equal,
                (true, false) => Ordering::Greater,
                (false, true) => Ordering::Less,
                _ => x.partial_cmp(&y).unwrap(),
            })
        }
    }
}

#[test]
fn the_three_lossy_decodings_decode_as_recorded() {
    let v = load("numbers/torture");
    let lossy = v["lossy_decodings"].as_array().unwrap();
    assert_eq!(lossy.len(), 3, "§7 names exactly three lossy cases");
    for l in lossy {
        let got = cke::decode_all(&unhex(l["cke"].as_str().unwrap())).unwrap();
        let want = build(&l["decodes_to"]);
        assert_eq!(got, want, "{}", l["why"]);
    }
}

