#[test]
fn the_dictionary_reproduces_the_recorded_encoding() {
    let v = load("documents/cases");
    let dict: Vec<(u32, String)> = v["dictionary"]
        .as_array()
        .unwrap()
        .iter()
        .map(|e| (e["name_id"].as_u64().unwrap() as u32, e["name"].as_str().unwrap().to_string()))
        .collect();
    let by_name = |n: &str| dict.iter().find(|(_, name)| name == n).map(|(id, _)| *id);
    let by_id = |id: u32| dict.iter().find(|(i, _)| *i == id).map(|(_, n)| n.clone());

    let c = &v["cases"][0];
    let doc = build(&c["value"]);
    let want = c["cve_with_dictionary"].as_str().unwrap();
    assert_eq!(hex(&cve::encode_with_dict(&doc, &by_name)), want);
    assert_eq!(
        hex(&cve::encode(&doc)),
        c["cve_without_dictionary"].as_str().unwrap(),
        "every name inline"
    );

    let back = cve::decode_all(&unhex(want), &by_id).unwrap();
    assert_eq!(back, doc);
    let order: Vec<String> =
        back.as_doc().unwrap().iter().map(|(k, _)| k.clone()).collect();
    let field_order: Vec<String> =
        c["field_order"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
    assert_eq!(order, field_order, "the field table is sorted by resolved name bytes");
}

#[test]
fn reserved_fields_occupy_name_id_1_to_5() {
    let v = load("documents/cases");
    let want = v["reserved_field_ids"].as_object().unwrap();
    // §5.4 names them in this order; the dictionary in the vector must agree.
    let reserved = ["_id", "_revision", "_modified", "_source", "_type"];
    for (i, name) in reserved.iter().enumerate() {
        assert_eq!(want[*name].as_u64().unwrap(), i as u64 + 1, "{name}");
    }
    assert_eq!(want.len(), reserved.len());
}

#[test]
fn an_unknown_tag_inside_an_array_round_trips_byte_for_byte() {
    let v = load("documents/cases");
    let c = &v["cases"][1];
    let bytes = unhex(c["cve"].as_str().unwrap());
    let back = cve::decode_all(&bytes, &|_| None).unwrap();
    assert_eq!(hex(&cve::encode(&back)), c["cve"].as_str().unwrap());
    assert_eq!(back, build(&c["value"]));
}

