#[test]
fn the_filter_structure_constants_reproduce() {
    let v = load("filter/blocked_bloom");
    let s = &v["structure"];
    assert_eq!(s["block_bits"].as_u64().unwrap() as usize, filter::BLOCK_BITS);
    for (bits, k) in s["probes_for_bits_per_key"].as_object().unwrap() {
        assert_eq!(
            filter::probes_for(bits.parse().unwrap()) as u64,
            k.as_u64().unwrap(),
            "probes at {bits} bits per key"
        );
    }
    let bc = &s["block_count_examples"];
    assert_eq!(bc["32 keys at 16 bits"].as_u64().unwrap(), filter::block_count_for(32, 16));
    assert_eq!(bc["33 keys at 16 bits"].as_u64().unwrap(), filter::block_count_for(33, 16));
    assert_eq!(bc["1000 keys at 16 bits"].as_u64().unwrap(), filter::block_count_for(1000, 16));
}

#[test]
fn the_named_hash_is_cfh64_and_its_vectors_reproduce() {
    let v = load("filter/blocked_bloom");
    assert!(v["hash"].as_str().unwrap().contains("CFH-64"));
    let vectors = v["cfh64_vectors"].as_object().unwrap();
    assert!(vectors.len() >= 6);
    for (key_hex, want) in vectors {
        let got = format!("{:x}", hash::cfh64(&unhex(key_hex)));
        assert_eq!(got, want.as_str().unwrap(), "CFH-64 of {key_hex}");
    }
}

#[test]
fn the_recorded_filter_blocks_reproduce_bit_for_bit() {
    let v = load("filter/blocked_bloom");
    let r = &v["reproduce"];
    let tree_id = r["tree_id"].as_u64().unwrap() as u32;
    let first = r["first_id"].as_i64().unwrap();
    let count = r["key_count"].as_u64().unwrap() as i64;
    let bits = r["bits_per_key"].as_u64().unwrap() as u32;
    let keys: Vec<Vec<u8>> = (0..count)
        .map(|i| {
            let k = cke::encode(&Value::NitriteId(first + i)).unwrap();
            filter::user_key_prefix(tree_id, &k)
        })
        .collect();
    let f = filter::BlockedBloom::build(&keys, bits, keys.len() as u64);
    assert_eq!(hex(&f.blocks), v["blocks"].as_str().unwrap());
    // The whole 20-byte header of §2.4, not a prefix of it: the blocks begin
    // at byte 20, and a reader that assumed 16 would misalign every block.
    let header = v["header_bytes"].as_str().unwrap();
    assert_eq!(header.len() / 2, 20);
    assert_eq!(hex(&f.encode_payload()[..20]), header);
    // A filter's failure mode is a silent false negative, so check there is none.
    assert!(keys.iter().all(|k| f.may_contain(k)));
}

