#[test]
fn the_subkeys_reproduce_and_differ_per_purpose() {
    let v = load("security/derivation");
    let s = &v["subkeys"];
    let master = unhex(s["master_key"].as_str().unwrap());
    let uuid: [u8; 16] = unhex(s["database_uuid"].as_str().unwrap()).try_into().unwrap();
    assert_eq!(s["info_prefix"].as_str().unwrap(), security::INFO_PREFIX);
    for purpose in ["page", "vlog", "sbmac"] {
        assert_eq!(
            hex(&security::subkey(&master, &uuid, purpose)),
            s[purpose].as_str().unwrap(),
            "subkey for {purpose}"
        );
    }
    assert_ne!(s["page"], s["vlog"]);
    assert_ne!(s["page"], s["sbmac"]);
}

#[test]
fn the_nonces_reproduce_and_are_24_bytes() {
    let v = load("security/derivation");
    for n in v["nonces"].as_array().unwrap() {
        let built = security::nonce(
            n["domain"].as_u64().unwrap() as u8,
            n["counter"].as_u64().unwrap(),
            n["object_id"].as_u64().unwrap(),
            n["offset"].as_u64().unwrap(),
        )
        .unwrap();
        assert_eq!(built.len(), 24);
        assert_eq!(hex(&built), n["nonce"].as_str().unwrap());
    }
    assert_eq!(
        v["nonce_watermark"]["gap"].as_u64().unwrap(),
        security::NONCE_GAP,
        "§4.1's published floor"
    );
}

#[test]
fn the_keyslot_layout_matches() {
    let v = load("security/derivation");
    let k = &v["keyslot"];
    use security::keyslot as ks;
    assert_eq!(k["size"].as_u64().unwrap() as usize, ks::SIZE);
    assert_eq!(k["count"].as_u64().unwrap() as usize, ks::COUNT);
    assert_eq!(k["offset_in_superblock"].as_u64().unwrap() as usize, ks::OFFSET_IN_SUPERBLOCK);
    assert_eq!(ks::SIZE * ks::COUNT, 576);
    assert_eq!(ks::OFFSET_IN_SUPERBLOCK + ks::SIZE * ks::COUNT, 4088, "keyslots end at the reserved tail");
    let offs = &k["field_offsets"];
    for (name, got) in [
        ("state", ks::STATE),
        ("kdf", ks::KDF),
        ("label_len", ks::LABEL_LEN),
        ("t_cost", ks::T_COST),
        ("m_cost_kib", ks::M_COST_KIB),
        ("parallelism", ks::PARALLELISM),
        ("salt", ks::SALT),
        ("wrap_nonce", ks::WRAP_NONCE),
        ("wrapped_key", ks::WRAPPED_KEY),
        ("wrap_tag", ks::WRAP_TAG),
        ("label", ks::LABEL),
    ] {
        assert_eq!(offs[name].as_u64().unwrap() as usize, got, "keyslot offset of {name}");
    }
}

#[test]
fn the_rfc9106_argon2id_vector_reproduces() {
    let v = load("security/derivation");
    let a = &v["argon2id"];
    let p = &a["params"];
    let (pwd, salt, secret, ad) = (
        unhex(a["password"].as_str().unwrap()),
        unhex(a["salt"].as_str().unwrap()),
        unhex(a["secret"].as_str().unwrap()),
        unhex(a["associated_data"].as_str().unwrap()),
    );
    let (m, t, par, tag_len) = (
        p["memory_kib"].as_u64().unwrap() as u32,
        p["passes"].as_u64().unwrap() as u32,
        p["parallelism"].as_u64().unwrap() as u32,
        p["tag_length"].as_u64().unwrap() as usize,
    );
    let h0 = security::argon2_h0(&pwd, &salt, &secret, &ad, t, m, par, tag_len as u32);
    assert_eq!(hex(&h0), a["h0"].as_str().unwrap(), "RFC 9106 §3.2 step 1");
    let tag = security::argon2id(&pwd, &salt, &secret, &ad, t, m, par, tag_len).unwrap();
    assert_eq!(hex(&tag), a["tag"].as_str().unwrap());
    assert_eq!(a["version"].as_u64().unwrap(), 0x13);
}

#[test]
fn the_profile_costs_are_at_or_above_the_writer_floor() {
    let v = load("security/derivation");
    let c = &v["profile_costs"];
    let floor = &c["writer_floor"];
    let (ft, fm, fp) = (
        floor["t_cost"].as_u64().unwrap(),
        floor["m_cost_kib"].as_u64().unwrap(),
        floor["parallelism"].as_u64().unwrap(),
    );
    for profile in ["mobile", "tablet", "desktop", "server"] {
        let p = &c[profile];
        assert!(p["t_cost"].as_u64().unwrap() >= ft, "{profile} t_cost");
        assert!(p["m_cost_kib"].as_u64().unwrap() >= fm, "{profile} m_cost");
        assert!(p["parallelism"].as_u64().unwrap() >= fp, "{profile} parallelism");
    }
}

