#[test]
fn a_descriptor_re_encodes_to_the_same_bytes() {
    let v = load("catalog/trees");
    for t in v["trees"].as_array().unwrap() {
        let name = t["name"].as_str().unwrap();
        assert_eq!(
            hex(&cke::encode(&Value::Str(name.to_string())).unwrap()),
            t["name_key"].as_str().unwrap(),
            "the catalog key of {name}"
        );
        let want = t["descriptor_without_created"].as_str().unwrap();
        let d = cve::decode_all(&unhex(want), &|_| None)
            .unwrap_or_else(|e| panic!("{name}: {e}"));
        match d.field("tree_id") {
            Some(Value::Int { mag, .. }) => {
                assert_eq!(*mag as u64, t["tree_id"].as_u64().unwrap(), "{name}")
            }
            other => panic!("{name}: tree_id is {other:?}"),
        }
        assert_eq!(d.field("kind"), Some(&Value::Str(t["kind"].as_str().unwrap().to_string())));
        assert_eq!(d.field("levelled"), Some(&Value::Bool(t["levelled"].as_bool().unwrap())));
        assert_eq!(hex(&cve::encode(&d)), want, "{name} must round-trip byte for byte");
    }
}

